selector_to_html = {"a[href=\"#frame-averaging\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Frame Averaging<a class=\"headerlink\" href=\"#frame-averaging\" title=\"Link to this heading\">#</a></h3><p>When <code class=\"docutils literal notranslate\"><span class=\"pre\">si.hStackManager.framesPerSlice</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">1</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">si.hStackManager.logAverageFactor</span> <span class=\"pre\">==</span> <span class=\"pre\">1</span></code>:</p>", "a[href=\"#id6\"]": "<figure class=\"align-default\" id=\"id6\">\n<img alt=\"../_images/ex_deinterleave_nobg.svg\" src=\"../_images/ex_deinterleave_nobg.svg\"/>\n<figcaption>\n<p><span class=\"caption-text\">Raw data are stored first by z-plane, for each timepoint (1) before being deinterleaved (2).\nThis example shows a session with 2 ROI\u2019s shown vertically stacked with a black bar of ~14 pixels in between.</span><a class=\"headerlink\" href=\"#id6\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#key-metadata\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Key Metadata<a class=\"headerlink\" href=\"#key-metadata\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#usage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Usage<a class=\"headerlink\" href=\"#usage\" title=\"Link to this heading\">#</a></h3><p>Each pipeline comes stocked with methods to retrieve imaging metadata.</p>", "a[href=\"#standard-2p\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Standard 2P<a class=\"headerlink\" href=\"#standard-2p\" title=\"Link to this heading\">#</a></h2><p>Non-LBM, non-piezo acquisitions for simpler imaging scenarios.</p>", "a[href=\"#frame-ordering\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Frame Ordering<a class=\"headerlink\" href=\"#frame-ordering\" title=\"Link to this heading\">#</a></h3><p>LBM saves z-planes interleaved as channels. There is no frame averaging because the piezo is not used.</p><p>ScanImage saves raw tiffs with each z-depth and timepoint interleaved [zT]:</p>", "a[href=\"#raw-data\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Raw Data<a class=\"headerlink\" href=\"#raw-data\" title=\"Link to this heading\">#</a></h3><p>ScanImage <a class=\"reference external\" href=\"https://docs.scanimage.org/Premium+Features/Multiple+Region+of+Interest+(MROI).html\">Multi Region Of Interest (mROI)</a> outputs raw <code class=\"docutils literal notranslate\"><span class=\"pre\">.tiff</span></code> files made up of individual <code class=\"docutils literal notranslate\"><span class=\"pre\">Regions</span> <span class=\"pre\">of</span> <span class=\"pre\">Interest</span> <span class=\"pre\">(ROI's)</span></code>.</p><p>In its raw form, data is saved as a 3-dimensional <a class=\"reference internal\" href=\"../ref.html#multipage-tiff\"><span class=\"std std-ref\">multi-page tiff file</span></a> with each ROI stacked vertically relative to the fast-galvo scan direction.</p>", "a[href=\"#isoview-light-sheet\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">IsoView Light-Sheet<a class=\"headerlink\" href=\"#isoview-light-sheet\" title=\"Link to this heading\">#</a></h2><p>IsoView is a multi-view light-sheet microscopy system for high-speed volumetric imaging.</p>", "a[href=\"#acquisition-types\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Acquisition Types<a class=\"headerlink\" href=\"#acquisition-types\" title=\"Link to this heading\">#</a></h2><p>The MBO supports several imaging modalities, each with distinct data organization:</p>", "a[href=\"../ref.html#multipage-tiff\"]": "<figure class=\"align-default\" id=\"multipage-tiff\">\n<img alt=\"Multipage Tiff\" src=\"../_images/gen_array_page.gif\"/>\n<figcaption>\n<p><span class=\"caption-text\">MultiPage Tiff</span><a class=\"headerlink\" href=\"#multipage-tiff\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#scanimage-hierarchy\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">ScanImage Hierarchy<a class=\"headerlink\" href=\"#scanimage-hierarchy\" title=\"Link to this heading\">#</a></h3><p>For ScanImage acquisitions, data is organized hierarchically:</p>", "a[href=\"../glossary.html#term-piezo\"]": "<dt id=\"term-piezo\">piezo</dt><dd><p>A piezoelectric actuator used to rapidly move the objective or sample stage along the z-axis. Enables fast volumetric imaging by sequentially stepping through z-positions. In ScanImage, controlled via <code class=\"docutils literal notranslate\"><span class=\"pre\">si.hStackManager</span></code> parameters.</p></dd>", "a[href=\"#optimized-lbm\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Optimized LBM<a class=\"headerlink\" href=\"#optimized-lbm\" title=\"Link to this heading\">#</a></h2><p>Data acquired on the <a class=\"reference external\" href=\"https://mbo.rockefeller.edu/tools/#opt-lbm\">optimized</a> or <a class=\"reference external\" href=\"https://mbo.rockefeller.edu/tools/#high-res\">high-res</a> light-beads microscopy (LBM) modules.</p>", "a[href=\"#array-terminology\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Array Terminology<a class=\"headerlink\" href=\"#array-terminology\" title=\"Link to this heading\">#</a></h2><p>All MBO datasets are stored as multi-dimensional arrays with consistent dimension ordering:</p>", "a[href=\"#piezo-stack\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Piezo Stack<a class=\"headerlink\" href=\"#piezo-stack\" title=\"Link to this heading\">#</a></h2><p>Piezo acquisitions use a <a class=\"reference internal\" href=\"../glossary.html#term-piezo\"><span class=\"xref std std-term\">piezo actuator</span></a> to sequentially move through z-positions, creating volumetric data.</p>", "a[href=\"#mbo-datasets\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">MBO Datasets<a class=\"headerlink\" href=\"#mbo-datasets\" title=\"Link to this heading\">#</a></h1><p>This guide describes data acquired at the Miller Brain Observatory using <a class=\"reference external\" href=\"https://docs.scanimage.org/index.html\">ScanImage</a> and light-sheet microscopy systems.</p>", "a[href=\"#data-format\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Data Format<a class=\"headerlink\" href=\"#data-format\" title=\"Link to this heading\">#</a></h3><p>Standard acquisitions are straightforward:</p>", "a[href=\"#data-formats\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Data Formats<a class=\"headerlink\" href=\"#data-formats\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#overview\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h3><p>ScanImage stores metadata about image size, frame rate, resolution, and regions of interest within the raw <code class=\"docutils literal notranslate\"><span class=\"pre\">.tiff</span></code> file.</p><p>Each pipeline handles this metadata for you, and provides an interface to use these values throughout the pipeline.</p>", "a[href=\"#frame-organization\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Frame Organization<a class=\"headerlink\" href=\"#frame-organization\" title=\"Link to this heading\">#</a></h3><p>Unlike LBM where z-planes are interleaved, piezo stacks acquire all frames at one z-position before moving to the next slice:</p>", "a[href=\"#scanimage-metadata\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">ScanImage Metadata<a class=\"headerlink\" href=\"#scanimage-metadata\" title=\"Link to this heading\">#</a></h2><p>The primary distinction between MBO datasets is how data is organized on disk. This information is stored in the <a class=\"reference external\" href=\"https://docs.scanimage.org/Appendix/ScanImage%2BBigTiff%2BSpecification.html#scanimage-bigtiff-specification\">ScanImage Metadata</a>.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
